    "header.processingTime": "4-6 Wochen ab Antragstellung",
    "header.requirements.0": "Mietvertrag",
    "header.requirements.1": "Die letzten 3 Gehaltsabrechnungen oder Einkommensnachweise",
    "header.requirements.2": "Meldebescheinigung",
    "header.requirements.3": "IBAN des Bankkontos",
    "header.requirements.4": "Nachweis über Nebenkosten",
    "header.commonMistakes.0": "An das Jobcenter statt an die Wohngeldstelle gehen",
    "header.commonMistakes.1": "Antrag nach 12 Monaten nicht erneuern",
    "header.commonMistakes.2": "Änderungen im Einkommen oder in der Miete nicht melden",
